import { render } from '@solidjs/web';
import { createSignal, For } from 'solid-js';

const names = { ada: 'Ada Lovelace', grace: 'Grace Hopper' };
function App() {
  const [person, setPerson] = createSignal('ada');
  const [draft, setDraft] = createSignal('Ada Lovelace');
  return (
    <>
      <label>
        Person{' '}
        <select
          value={person()}
          onChange={(event) => setPerson(event.currentTarget.value)}
        >
          <For each={Object.keys(names)}>
            {(key) => <option value={key}>{names[key]}</option>}
          </For>
        </select>
      </label>
      <label>
        Draft name{' '}
        <input
          value={draft()}
          onInput={(event) => setDraft(event.currentTarget.value)}
        />
      </label>
      <p>Draft: {draft()}</p>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createSignal, For } from 'solid-js';

const names = { ada: 'Ada Lovelace', grace: 'Grace Hopper' };
function App() {
  const [person, setPerson] = createSignal('ada');
  const [draft, setDraft] = createSignal(() => names[person()]);
  return (
    <>
      <label>
        Person{' '}
        <select
          value={person()}
          onChange={(event) => setPerson(event.currentTarget.value)}
        >
          <For each={Object.keys(names)}>
            {(key) => <option value={key}>{names[key]}</option>}
          </For>
        </select>
      </label>
      <label>
        Draft name{' '}
        <input
          value={draft()}
          onInput={(event) => setDraft(event.currentTarget.value)}
        />
      </label>
      <p>Draft: {draft()}</p>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
